result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "pinyin.py", "content": """"Convert numbered pinyin syllables (e.g. 'ni3') to diacritic form (e.g. 'nǐ')."""

import unicodedata

# Precomposed vowel + tone-mark characters, indexed by tone (1-4).
_MARKS = {
    1: {"a": "ā", "e": "ē", "i": "ī", "o": "ō", "u": "ū", "ü": "ǖ"},
    2: {"a": "á", "e": "é", "i": "í", "o": "ó", "u": "ú", "ü": "ǘ"},
    3: {"a": "ǎ", "e": "ě", "i": "ǐ", "o": "ǒ", "u": "ǔ", "ü": "ǚ"},
    4: {"a": "à", "e": "è", "i": "ì", "o": "ò", "u": "ù", "ü": "ǜ"},
}

_VOWELS = set("aeiouü")


def _find_mark_index(syllable):
    """Return index of the character that receives the tone mark."""
    # 1) on 'a' if present
    idx = syllable.find("a")
    if idx != -1:
        return idx
    # 2) else on 'e'
    idx = syllable.find("e")
    if idx != -1:
        return idx
    # 3) else on 'o' in 'ou'
    if "ou" in syllable:
        return syllable.find("ou")
    # 4) else on the LAST vowel
    for i in range(len(syllable) - 1, -1, -1):
        if syllable[i] in _VOWELS:
            return i
    raise ValueError(f"no vowel found to carry tone mark: {syllable!r}")


def convert(syllable):
    """Convert a single numbered syllable like 'ni3' or 'lv4' to diacritic form."""
    syllable = unicodedata.normalize("NFC", syllable)
    if len(syllable) >= 2 and syllable[-1].isdigit():
        tone = int(syllable[-1])
        base = syllable[:-1]
        if tone not in _MARKS:
            raise ValueError(f"invalid tone digit {tone!r} in {syllable!r}")
        # accept 'v' as ü
        if "v" in base:
            base = base.replace("v", "ü")
        i = _find_mark_index(base)
        marked = _MARKS[tone][base[i]]
        result = base[:i] + marked + base[i + 1:]
        return unicodedata.normalize("NFC", result)
    # neutral tone (no trailing digit): unchanged
    return syllable


def convert_text(s):
    """Convert whitespace-separated numbered syllables to diacritic form."""
    return " ".join(convert(token) for token in s.split())
